<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Camera,Plus,CheckCircle2,Send,CarFront,ClipboardCheck,FileText,Wrench} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import StatusBadge from '../../components/StatusBadge.vue';import {useWorkshop} from '../../composables/useWorkshop';import type {WorkOrderStatus,InspectionState} from '../../data/company';import {useVintro} from '../../composables/useVintro';const route=useRoute();const {state,setWorkOrderStatus,setInspectionState,completeService}=useWorkshop();const {notify,addService}=useVintro();const order=computed(()=>state.workOrders.find(w=>w.id===route.params.id)??state.workOrders[0]);const tab=ref('Overview');const states:InspectionState[]=['OK','Monitor','Replace soon','Replace immediately'];const workflow:WorkOrderStatus[]=['Booked','Checked-in','Inspection','Waiting approval','Repair','Ready','Completed'];const sendQuote=()=>{setWorkOrderStatus(order.value.id,'Waiting approval');notify('Quote sent to customer')};const complete=()=>{completeService(order.value.id);addService({id:crypto.randomUUID(),date:'26 August 2026',dateISO:'2026-08-26',mileage:order.value.mileage,type:order.value.requested,category:'Service',workshop:'Garage Jerala',parts:order.value.parts.map(p=>p.name),notes:order.value.notes,cost:Math.round(total.value),currency:'EUR',verified:true});notify('Service completed and verified record created')};const total=computed(()=>order.value.labour.reduce((s,l)=>s+l.hours*l.rate,0)+order.value.parts.reduce((s,p)=>s+p.quantity*p.price,0))
</script>
<template><WorkshopHeader :title="order.id" :subtitle="`${order.vehicle} · ${order.registration}`" back="/workshop/orders"><StatusBadge :status="order.status"/></WorkshopHeader><div class="mx-auto max-w-[1200px] p-5 md:p-8"><div class="overflow-x-auto"><div class="flex min-w-max gap-2"><button v-for="t in ['Overview','Inspection','Work & parts','Quote','History']" @click="tab=t" class="rounded-full px-4 py-2 text-sm font-medium" :class="tab===t?'bg-ink text-white':'border bg-white'">{{t}}</button></div></div><div class="mt-6 grid gap-6 lg:grid-cols-[1fr_310px]"><div><section v-if="tab==='Overview'" class="space-y-5"><div class="rounded-2xl border bg-white p-5"><div class="flex items-center gap-2"><CarFront :size="20"/><h2 class="section-title">Vehicle & request</h2></div><dl class="mt-5 grid gap-4 sm:grid-cols-2"><div><dt class="text-xs text-muted">Customer</dt><dd class="mt-1 font-semibold">{{order.customer}}</dd></div><div><dt class="text-xs text-muted">Vehicle</dt><dd class="mt-1 font-semibold">{{order.vehicle}}</dd></div><div><dt class="text-xs text-muted">VIN</dt><dd class="nums mt-1 text-sm font-semibold">{{order.vin}}</dd></div><div><dt class="text-xs text-muted">Mileage</dt><dd class="nums mt-1 font-semibold">{{order.mileage.toLocaleString()}} km</dd></div></dl><div class="mt-5 rounded-xl bg-stone-50 p-4"><p class="text-xs text-muted">Requested work</p><p class="mt-1 font-semibold">{{order.requested}}</p><p class="mt-2 text-sm text-muted">{{order.notes}}</p></div></div><div class="rounded-2xl border bg-white p-5"><h2 class="section-title">Relevant service history</h2><div class="mt-4 divide-y"><div v-for="h in [{date:'15 May 2026',text:'Engine oil & filter · 84,840 km'},{date:'12 October 2025',text:'Front brakes · 72,300 km'}]" class="py-3"><strong class="block text-sm">{{h.text}}</strong><small class="text-muted">{{h.date}} · Workshop verified</small></div></div></div></section><section v-else-if="tab==='Inspection'" class="space-y-3"><div v-for="item in order.inspection" class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-semibold">{{item.category}}</h3><p class="mt-1 text-sm text-muted">{{item.measurement}} · {{item.note}}</p></div><select :value="item.state" @change="setInspectionState(order.id,item.category,($event.target as HTMLSelectElement).value as InspectionState)" class="rounded-lg border px-3 py-2 text-xs font-semibold"><option v-for="s in states">{{s}}</option></select></div><div class="mt-4 flex justify-between border-t pt-3 text-sm"><span>{{item.action}}</span><span v-if="item.photo" class="flex items-center gap-1 text-accent"><Camera :size="15"/>Photo</span></div></div><button class="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed py-5 text-sm font-semibold"><Plus :size="17"/>Add inspection category</button></section><section v-else-if="tab==='Work & parts'" class="space-y-5"><div class="rounded-2xl border bg-white p-5"><div class="flex justify-between"><h2 class="section-title">Labour</h2><button class="text-sm font-semibold text-accent">+ Add</button></div><div class="mt-4 divide-y"><div v-for="l in order.labour" class="flex justify-between py-3 text-sm"><span>{{l.name}} · {{l.hours}} h</span><strong class="nums">€{{(l.hours*l.rate).toFixed(2)}}</strong></div></div></div><div class="rounded-2xl border bg-white p-5"><div class="flex justify-between"><h2 class="section-title">Parts</h2><button class="text-sm font-semibold text-accent">+ Add</button></div><div class="mt-4 divide-y"><div v-for="p in order.parts" class="flex justify-between py-3 text-sm"><span>{{p.quantity}} × {{p.name}}</span><strong class="nums">€{{(p.quantity*p.price).toFixed(2)}}</strong></div><p v-if="!order.parts.length" class="py-4 text-sm text-muted">No parts added yet.</p></div></div><button class="btn-secondary w-full"><Camera :size="17"/>Add work photos</button></section><section v-else-if="tab==='Quote'" class="rounded-2xl border bg-white p-5"><div class="flex items-center gap-2"><FileText :size="20"/><h2 class="section-title">Additional work quote</h2></div><label class="mt-5 block"><span class="label">Recommendation</span><textarea class="field min-h-24" :value="order.recommendation"/></label><div class="mt-4 flex justify-between text-sm"><span>Labour & parts</span><strong class="nums">€{{total.toFixed(2)}}</strong></div><div class="mt-2 flex justify-between text-sm"><span>VAT (22%)</span><strong class="nums">€{{(total*.22).toFixed(2)}}</strong></div><div class="mt-4 flex justify-between border-t pt-4"><strong>Total</strong><strong class="nums text-xl">€{{(total*1.22).toFixed(2)}}</strong></div><button @click="sendQuote" class="btn-primary mt-6 w-full"><Send :size="17"/>Send quote to customer</button></section><section v-else class="rounded-2xl border bg-white p-5"><h2 class="section-title">Work order history</h2><div class="mt-5 space-y-5"><div v-for="(s,i) in workflow.slice(0,workflow.indexOf(order.status)+1)" class="flex gap-3"><CheckCircle2 :size="18" class="text-success"/><span><strong class="block text-sm">{{s}}</strong><small class="text-muted">{{i===0?'Booking created':'Updated by workshop team'}}</small></span></div></div></section></div><aside><div class="sticky top-24 space-y-4"><section class="rounded-2xl border bg-white p-5"><h2 class="text-sm font-semibold">Workflow</h2><select :value="order.status" @change="setWorkOrderStatus(order.id,($event.target as HTMLSelectElement).value as WorkOrderStatus)" class="field mt-3"><option v-for="s in workflow">{{s}}</option></select><div class="mt-5"><p class="text-xs text-muted">Assigned technician</p><p class="mt-1 font-semibold">{{order.technician}}</p></div><div class="mt-4"><p class="text-xs text-muted">Photos</p><p class="mt-1 font-semibold">{{order.photos}} attached</p></div></section><button v-if="order.status!=='Completed'" @click="complete" class="btn-primary w-full"><ClipboardCheck :size="18"/>Complete service</button><div class="rounded-2xl bg-emerald-50 p-4 text-sm leading-6 text-muted"><strong class="block text-success">Vintro connected</strong>Completion creates a workshop-verified record in the customer’s vehicle history.</div></div></aside></div></div></template>
